        }

        @Test("All errors have unique descriptions")
        func allErrorsHaveUniqueDescriptions() {
            // Arrange
            let errors: [AIError] = [
                .invalidResponse,
                .networkError(NSError(domain: "test", code: 1)),
                .apiError("test error")
            ]

            // Act
            let descriptions = errors.compactMap { $0.errorDescription }

            // Assert
