    // MARK: - Commentary Workflow Tests

    @Suite("Commentary Workflow")
    struct CommentaryWorkflowTests {

        @Test("WorkflowBrief combines text and voice instructions")
        func workflowBriefCombinesPromptSources() {
            let brief = WorkflowBrief(
                workflow: .commentary,
                instructions: "Group the errors by concept.",
                voiceBriefSummary: "Keep the source timestamp visible.",
                maxMoments: 5
            )

            #expect(brief.hasContent)
            #expect(brief.combinedPrompt == "Group the errors by concept.\nKeep the source timestamp visible.")
        }

        @Test("CommentaryPlanItem mirrors commentary markers")
        func commentaryPlanItemFromMarkersPreservesOrder() {
            let markers = [
                CommentaryMarker(
                    concept: "Second",
                    title: "Second point",
                    startTime: 30,
                    endTime: 36,
                    scriptureReferences: "Acts 17:11",
                    sortOrder: 1
                ),
                CommentaryMarker(
                    concept: "First",
                    title: "First point",
                    startTime: 12,
                    endTime: 18,
                    scriptureReferences: "1 Timothy 5:21",
                    sortOrder: 0
                )
            ]

            let items = CommentaryPlanItem.fromMarkers(markers)

            #expect(items.count == 2)
            #expect(items[0].concept == "First")
            #expect(items[0].claim == "First point")
            #expect(items[0].supportingReferences == "1 Timothy 5:21")
            #expect(items[1].concept == "Second")
            #expect(items[1].startTime == 30)
        }

        @Test("Local SaneAI workflow parser converts workflow JSON into plan items")
        func localWorkflowParserBuildsPlanItems() throws {
            let response = """
            helper noise
            {
              "workflow": "meetingReview",
              "summary": "Capture the release hold.",
              "items": [
                {
                  "concept": "Hold The Release",
                  "claim": "Do not ship until timestamps are fixed.",
                  "supportingReferences": "PM review",
                  "sourceExcerpt": "Let's hold the release until the timestamps are fixed.",
                  "startTime": 42,
                  "endTime": 58,
                  "confidence": 0.91
                },
                {
                  "concept": "Fix Timestamps",
                  "claim": "Resolve the broken timestamp import path.",
                  "supportingReferences": "",
                  "sourceExcerpt": "The importer is still shifting everything by two hours.",
                  "startTime": 59,
                  "endTime": 74,
                  "confidence": 0.84
                }
              ]
            }
            trailing noise
            """

            let items = try LocalSaneAIWorkflowRunner.parsePlan(from: Data(response.utf8))

            #expect(items.count == 2)
            #expect(items[0].concept == "Hold The Release")
            #expect(items[0].claim.contains("Do not ship"))
            #expect(items[0].supportingReferences == "PM review")
            #expect(items[0].startTime == 42)
            #expect(items[1].concept == "Fix Timestamps")
            #expect(items[1].sourceExcerpt.contains("two hours"))
        }
    }

    // MARK: - MagicFixAnalysis Tests

    @Suite("MagicFixAnalysis")
    struct MagicFixAnalysisTests {

        @Test("Segment stores all properties")
        func segmentStoresProperties() {
            // Arrange & Act
            let segment = MagicFixAnalysis.Segment(
                startTime: 10.5,
                endTime: 15.0,
                description: "Introduction",
                type: .topic
            )

            // Assert
            #expect(segment.startTime == 10.5)
            #expect(segment.endTime == 15.0)
            #expect(segment.description == "Introduction")
            #expect(segment.type == .topic)
        }

        @Test("SegmentType has all expected cases")
        func segmentTypeHasAllCases() {
            // Arrange & Act
            let types: [MagicFixAnalysis.Segment.SegmentType] = [.filler, .topic, .highlight, .silence]

            // Assert
            let expectedTypes: Set<MagicFixAnalysis.Segment.SegmentType> = [.filler, .topic, .highlight, .silence]
            #expect(Set(types) == expectedTypes)
        }

        @Test("SegmentType rawValues are correct")
        func segmentTypeRawValues() {
            // Assert
            #expect(MagicFixAnalysis.Segment.SegmentType.filler.rawValue == "filler")
            #expect(MagicFixAnalysis.Segment.SegmentType.topic.rawValue == "topic")
            #expect(MagicFixAnalysis.Segment.SegmentType.highlight.rawValue == "highlight")
            #expect(MagicFixAnalysis.Segment.SegmentType.silence.rawValue == "silence")
        }

        @Test("MagicFixAnalysis stores segments")
        func storesSegments() {
            // Arrange
            let segments = [
                MagicFixAnalysis.Segment(startTime: 0, endTime: 5, description: "Intro", type: .topic),
                MagicFixAnalysis.Segment(startTime: 10, endTime: 11, description: "Um...", type: .filler)
            ]

            // Act
            let analysis = MagicFixAnalysis(segments: segments)

            // Assert
            #expect(analysis.segments.count == 2)
            #expect(analysis.segments[0].type == .topic)
            #expect(analysis.segments[1].type == .filler)
        }

        @Test("MagicFixAnalysis is Codable")
        func isCodable() throws {
            // Arrange
            let analysis = MagicFixAnalysis(segments: [
                MagicFixAnalysis.Segment(startTime: 0, endTime: 5, description: "Test", type: .highlight)
            ])

            // Act
            let data = try JSONEncoder().encode(analysis)
            let decoded = try JSONDecoder().decode(MagicFixAnalysis.self, from: data)

            // Assert
            #expect(decoded.segments.count == 1)
            #expect(decoded.segments[0].type == .highlight)
            #expect(decoded.segments[0].description == "Test")
        }

        @Test("Segment is Codable")
        func segmentIsCodable() throws {
            // Arrange
            let segment = MagicFixAnalysis.Segment(
                startTime: 12.5,
                endTime: 13.0,
                description: "Umm...",
                type: .filler
            )

            // Act
            let data = try JSONEncoder().encode(segment)
            let decoded = try JSONDecoder().decode(MagicFixAnalysis.Segment.self, from: data)

            // Assert
            #expect(decoded.startTime == 12.5)
            #expect(decoded.endTime == 13.0)
            #expect(decoded.type == .filler)
        }

        @Test("Empty segments array is valid")
        func emptySegmentsValid() {
            // Arrange & Act
            let analysis = MagicFixAnalysis(segments: [])

            // Assert
            #expect(analysis.segments.isEmpty)
        }
    }

